5. /// <summary>
6. /// Masks account identifiers and monetary amounts out of free-text audit fields.
7. ///
8. /// Reason and evidence are caller supplied, so they are the only channel through which
9. /// account numbers or trade amounts could reach durable audit history, an export or a
10. /// diagnostic message. Values are redacted once, on the way in, so no downstream
11. /// consumer can leak them (INV-5 / NFR-1).
12. ///
13. /// Redaction is deliberately conservative: ordinary prose, ISO business dates and small
14. /// counts survive untouched, so a clean reason such as "Client confirmed the break" is
15. /// exported verbatim.
16. /// </summary>
17. public static partial class SensitiveDataRedactor
18. {
19.     public const string IdentifierMask = "[REDACTED-IDENTIFIER]";
20.     public const string AmountMask = "[REDACTED-AMOUNT]";
21. 
22.     /// <summary>Returns <paramref name="value"/> with account-like and amount-like tokens masked.</summary>
23.     public static string Redact(string? value)
24.     {
25.         if (string.IsNullOrEmpty(value))
26.         {
27.             return string.Empty;
28.         }
29. 
30.         return TokenPattern().Replace(value, match => Classify(match.Value));
31.     }
32. 
33.     private static string Classify(string token)
34.     {
35.         var trimmed = token.TrimEnd('.', ',', '-', '/', '_');
36.         var suffix = token[trimmed.Length..];
37. 
38.         if (trimmed.Length == 0)
39.         {
40.             return token;
41.         }
42. 
43.         if (IsoDatePattern().IsMatch(trimmed))
44.         {
45.             return token;
46.         }
47. 
48.         var letters = 0;
49.         var digits = 0;
50.         foreach (var c in trimmed)
51.         {
52.             if (char.IsLetter(c))
53.             {
54.                 letters++;
55.             }
56.             else if (char.IsDigit(c))
57.             {
58.                 digits++;
59.             }
60.         }
61. 
62.         if (digits == 0)
63.         {
64.             return token;
65.         }
66. 
67.         if (letters > 0)
68.         {
69.             // Mixed alphanumeric tokens with more than one digit look like record or
70.             // account identifiers (ACC001, ACCT-4242, SENTINEL-ACCOUNT-9911).
71.             return digits >= 2 ? IdentifierMask + suffix : token;
72.         }
73. 
74.         var hasFraction = FractionPattern().IsMatch(trimmed);
75.         var hasGrouping = trimmed.Contains(',', StringComparison.Ordinal);
76.         if (hasFraction || hasGrouping || digits >= 4)
77.         {
78.             return AmountMask + suffix;
79.         }
80. 
81.         return token;
82.     }
