3. 
4. namespace TradeRecon.Tests;
5. 
6. /// <summary>Sensitive-data boundary of the audit workflow (REQ-8, INV-5, NFR-1, AC-10).</summary>
7. public class AuditSensitiveDataTests : IDisposable
8. {
9.     private readonly string _state = AuditTestHarness.NewStateDirectory();
10. 
11.     public void Dispose()
12.     {
13.         if (Directory.Exists(_state))
14.         {
15.             Directory.Delete(_state, recursive: true);
16.         }
17. 
18.         GC.SuppressFinalize(this);
19.     }
20. 
21.     [Theory]
22.     [InlineData("ACC001")]
23.     [InlineData("ACCT-SENTINEL-90210")]
24.     [InlineData("account 4455-8899")]
25.     [InlineData("8675309.42")]
26.     [InlineData("1,600,500.00")]
27.     [InlineData("EUR 1600500")]
28.     public void Account_and_amount_shaped_tokens_are_masked(string text)
29.     {
30.         var redacted = SensitiveDataRedactor.Redact(text);
31. 
32.         Assert.DoesNotContain("ACC001", redacted, StringComparison.OrdinalIgnoreCase);
33.         Assert.DoesNotContain("90210", redacted, StringComparison.Ordinal);
34.         Assert.DoesNotContain("8675309", redacted, StringComparison.Ordinal);
35.         Assert.DoesNotContain("1600500", redacted, StringComparison.Ordinal);
36.         Assert.DoesNotContain("4455", redacted, StringComparison.Ordinal);
37.     }
38. 
39.     [Theory]
40.     [InlineData("Broker confirmed the break", "Broker confirmed the break")]
41.     [InlineData("Confirmed on 2024-06-03 by operations", "Confirmed on 2024-06-03 by operations")]
42.     [InlineData("Escalated twice within 24 hours", "Escalated twice within 24 hours")]
43.     public void Ordinary_explanations_survive_redaction_unchanged(string text, string expected)
44.     {
45.         Assert.Equal(expected, SensitiveDataRedactor.Redact(text));
46.     }
47. 
48.     [Fact]
49.     public void Sentinels_supplied_in_reason_and_evidence_never_reach_the_export_or_output()
50.     {
51.         var service = AuditTestHarness.Service(_state);
52.         service.Initialize();
53. 
54.         var reason = $"Break on account {AuditTestHarness.AccountSentinel} for {AuditTestHarness.AmountSentinel}";
55.         var evidence = $"custodian statement lists {AuditTestHarness.AmountSentinel} against {AuditTestHarness.AccountSentinel}";
56. 
57.         var proposal = service.Propose("REQ-800", "maker-a", "2024-06-03", reason, evidence);
58.         var decision = service.Decide("REQ-800", "checker-b", "approve");
59.         var export = service.Export("2024-06-01", "2024-06-30", AuditTestHarness.ExportPath(_state));
60. 
61.         var surfaces = new[]
62.         {
63.             proposal.ToJson(),
64.             decision.ToJson(),
65.             export.ToJson(),
66.             File.ReadAllText(AuditTestHarness.ExportPath(_state)),
67.             File.ReadAllText(service.Store.HistoryPath)
68.         };
69. 
70.         foreach (var surface in surfaces)
